def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c] != 0]

    best = None
    best_map = None
    for ph in range(1, h + 1):
        for pw in range(1, w + 1):
            mapping = {}
            valid = True
            for r, c, color in points:
                key = (r % ph, c % pw)
                if key in mapping and mapping[key] != color:
                    valid = False
                    break
                mapping[key] = color
            if valid:
                score = (ph * pw, ph + pw, ph, pw)
                if best is None or score < best:
                    best, best_map = score, mapping

    ph, pw = best[2], best[3]
    return [[best_map.get((r % ph, c % pw), 0) for c in range(w)]
            for r in range(h)]
